        foreach(var bad in new[]{valid.Replace("afterDamageApplied","beforeDamageApplied"),valid.Replace("damageSource","owner"),valid.Replace("perDamage","perCardUse"),valid.Replace("\"optional\":true","\"optional\":false"),valid.Replace("\"target\":\"owner\"","\"target\":\"selectedTarget\""),valid.Replace("\"target\":\"owner\"","\"target\":\"owner\",\"amount\":1"),"\"activations\":["+Act("bad","[{\"op\":\"obtainDamageTargetCardAndResolveCategory\",\"target\":\"owner\"}]")+"]"}){var rejected=false;try{Load("fixture:bad",bad);}catch(InvalidOperationException){rejected=true;}Require(rejected,"Wrong compound composition is rejected.");}
