            var p=P(g)!;Require(p.Choices.Any(c=>c.Parameters["source-zone"]=="Hand"&&c.Cards.Count==0)&&p.Choices.Any(c=>c.Cards.Contains(card.Id)),"Hidden hand opaque/public equipment offered for actual Obtain, including protected equipment.");
